{"path": "two_bucket.py", "content": "from collections import deque


def measure(bucket_one, bucket_two, goal, start_bucket):
    if start_bucket not in ("one", "two"):
        raise ValueError("start_bucket must be 'one' or 'two'")
    if goal > max(bucket_one, bucket_two) or goal < 0:
        raise ValueError("goal is impossible to reach")

    sizes = (bucket_one, bucket_two)
    start = 0 if start_bucket == "one" else 1
    other = 1 - start

    def forbidden(state):
        return state[start] == 0 and state[other] == sizes[other]

    def neighbours(state):
        a, b = state
        cap_a, cap_b = sizes
        pour_ab = min(a, cap_b - b)
        pour_ba = min(b, cap_a - a)
        return [
            (cap_a, b), (a, cap_b),          # fill
            (0, b), (a, 0),                  # empty
            (a - pour_ab, b + pour_ab),      # pour one -> two
            (a + pour_ba, b - pour_ba),      # pour two -> one
        ]

    first = [0, 0]
    first[start] = sizes[start]
    first = tuple(first)

    queue = deque([(first, 1)])
    seen = {(0, 0), first}
    while queue:
        state, moves = queue.popleft()
        if state[0] == goal:
            return moves, "one", state[1]
        if state[1] == goal:
            return moves, "two", state[0]
        for nxt in neighbours(state):
            if nxt in seen or forbidden(nxt):
                continue
            seen.add(nxt)
            queue.append((nxt, moves + 1))

    raise ValueError("goal is impossible to reach")
